import{_ as e,o as a,c as l,X as i}from"./chunks/framework.92e7fb7b.js";const p=JSON.parse('{"title":"长列表大表单性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/coding-learning-record/element-ui.md","filePath":"blogs/coding-learning-record/element-ui.md"}'),o={name:"blogs/coding-learning-record/element-ui.md"},t=i('<h1 id="长列表大表单性能优化" tabindex="-1">长列表大表单性能优化 <a class="header-anchor" href="#长列表大表单性能优化" aria-label="Permalink to &quot;长列表大表单性能优化&quot;">​</a></h1><h2 id="业务场景" tabindex="-1">业务场景 <a class="header-anchor" href="#业务场景" aria-label="Permalink to &quot;业务场景&quot;">​</a></h2><p>vue2 项目 400个表单需要校验。每个表单有20个左右的校验项，多选，单选，input，图片上传组件。总的组件数有上万个。页面性能问题严重。</p><p>200多个物料的场景就卡的动不了。</p><h2 id="落地选型" tabindex="-1">落地选型 <a class="header-anchor" href="#落地选型" aria-label="Permalink to &quot;落地选型&quot;">​</a></h2><ol><li>虚拟列表路线 <ol><li>不定高度内容，快速滚动会产生高度跳变；虚拟列表滚动，调研中遇到了动态选10个显示 高度跳变的问题。也有解决方案，但实现成本大，也有loading</li><li>表单提交时前端校验需要校验所有数据，需要改造校验逻辑</li></ol></li><li>简略列表+单个sku表单 <ol><li>表单提交时前端校验需要校验所有数据，需要改造校验逻辑（同上2）</li></ol></li></ol><p>总结： 虚拟列表路线 多了个 不定高度虚拟列表处理。体验产品、业务同学也认为单个sku表单更合理</p><h2 id="技术难点" tabindex="-1">技术难点 <a class="header-anchor" href="#技术难点" aria-label="Permalink to &quot;技术难点&quot;">​</a></h2><ul><li>简略列表+单个sku表单 <ol><li>整体表单校验；使用nexTick方式，替换数据，循环赋值。</li><li>重写校验方法，引入validate，读取elForm下面的elFormitem数据，拿到需要校验的validator。循环列表传入数据；结果几乎是把elForm的核心校验逻辑走了一遍。</li></ol></li></ul>',9),r=[t];function n(s,c,d,_,h,u){return a(),l("div",null,r)}const f=e(o,[["render",n]]);export{p as __pageData,f as default};
